select o.id,o.state,p.id as payment_id,p.state as payment_state,r.id as refund_id,r.state as refund_state,r.amount,r.refund_method from orders o join payments p on p.order_id=o.id left join refunds r on r.order_id=o.id where o.id in (1117,1118,1122) order by o.id; select id,session_id,type,amount,reference from cash_register_movements where session_id=115 order by id; select id,status,expected_closing_amount,actual_closing_amount,difference from cash_register_sessions where id=115; select id,is_active from cash_registers where id=60;
